+        if (stay.nights() < MINIMUM_NIGHTS) {
+            throw new HotelException(
+                    ErrorCode.INVALID_REQUEST,
+                    "the long stay plan needs at least " + MINIMUM_NIGHTS + " nights");
+        }
+    }
