    22	    /** The nights of the stay at the room's rate, with the plan's discount on their sum. */
    23	    static Price nightsWithDiscount(Stay stay, BigDecimal discountRate) {
    24	        BigDecimal subtotal = cents(BigDecimal.ZERO);
    25	        for (LocalDate night = stay.checkIn(); night.isBefore(stay.checkOut()); night = night.plusDays(1)) {
    26	            subtotal = subtotal.add(nightPrice(stay.room(), night));
    27	        }
